const ticket = $input.item.json.body ?? {};

const errors = [];

const ticketId = ticket.ticketId;
const customerEmail = ticket.customerEmail;
const message = ticket.message;

// Validate ticket ID
if (
  typeof ticketId !== "string" ||
  ticketId.trim() === ""
) {
  errors.push("Invalid ticket ID");
}

// Validate customer email
if (
  typeof customerEmail !== "string" ||
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail)
) {
  errors.push("Invalid customer email");
}

// Validate ticket message
if (
  typeof message !== "string" ||
  message.trim() === ""
) {
  errors.push("Invalid ticket message");
}

return {
  json: {
    ticketId: typeof ticketId === "string"
      ? ticketId.trim()
      : null,
    customerEmail: typeof customerEmail === "string"
      ? customerEmail.trim()
      : null,
    message: typeof message === "string"
      ? message.trim()
      : null,
    isValid: errors.length === 0,
    errors,
    status: errors.length === 0
      ? "VALIDATED"
      : "VALIDATION_ERROR"
  }
};
